{"implementation": "import math

def solve(case):
    sentence_vectors = case["sentence_vectors"]
    query_vector = case["query_vector"]
    context_weight = case["context_weight"]
    if not sentence_vectors:
        return {"similarities": [], "best_index": None}
    n = len(sentence_vectors[0])
    context_avg = [sum(sv[i] for sv in sentence_vectors) / len(sentence_vectors) for i in range(n)]
    blended_query = [(1 - context_weight) * q + context_weight * c for q, c in zip(query_vector, context_avg)]
    def cosine_similarity(a, b):
        dot = sum(x*y for x,y in zip(a,b))
        norm_a = math.sqrt(sum(x*x for x in a))
        norm_b = math.sqrt(sum(y*y for y in b))
        if norm_a == 0 or norm_b == 0:
            return 0.0
        return dot / (norm_a * norm_b)
    similarities = [cosine_similarity(sv, blended_query) for sv in sentence_vectors]
    best_index = max(range(len(similarities)), key=lambda i: similarities[i])
    return {"similarities": similarities, "best_index": best_index}
"}
